import React, { useState, useEffect, useCallback, useMemo } from 'react';
import Lightbox from 'yet-another-react-lightbox';
import 'yet-another-react-lightbox/styles.css';
import { useLanguage } from '../contexts/LanguageContext';

const Gallery = () => {
  const { t } = useLanguage();
  const [images, setImages] = useState([]);
  const [filteredImages, setFilteredImages] = useState([]);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [lightboxIndex, setLightboxIndex] = useState(0);
  const [loading, setLoading] = useState(true);
  const [loadedImages, setLoadedImages] = useState(new Set());
  const [currentPage, setCurrentPage] = useState(1);
  const imagesPerPage = 12;

  useEffect(() => {
    fetchGalleryImages();
  }, []);

  useEffect(() => {
    if (selectedCategory === 'all') {
      setFilteredImages(images);
    } else {
      setFilteredImages(images.filter(img => img.category === selectedCategory));
    }
    setCurrentPage(1); // Reset to first page when category changes
  }, [selectedCategory, images]);

  const fetchGalleryImages = async () => {
    try {
      // Fetch from Laravel API
      const response = await fetch('http://127.0.0.1:8000/api/gallery');
      const result = await response.json();

      // Laravel returns paginated data with 'data' property
      const apiData = result.data || result;

      // Transform API data
      const transformedImages = apiData.map(item => ({
        id: item.id,
        src: item.image_path || 'https://images.unsplash.com/photo-1564507592333-c60657eea523?w=800',
        thumbnail: item.image_path || 'https://images.unsplash.com/photo-1564507592333-c60657eea523?w=400',
        title: item.title || 'Untitled',
        category: item.category || 'Monuments',
        description: item.description || 'No description available',
      }));

      console.log('Fetched gallery from API:', transformedImages);
      setImages(transformedImages);
      setFilteredImages(transformedImages);
      setLoading(false);
    } catch (error) {
      console.error('Error fetching gallery:', error);
      // Fallback to mock data
      const mockImages = [
        {
          id: 1,
          src: 'https://images.unsplash.com/photo-1564507592333-c60657eea523?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1564507592333-c60657eea523?w=400',
          title: 'Taj Mahal',
          category: 'Monuments',
          description: 'The iconic white marble mausoleum in Agra, India',
        },
        {
          id: 2,
          src: 'https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1552832230-c0197dd311b5?w=400',
          title: 'Colosseum',
          category: 'Monuments',
          description: 'Ancient Roman amphitheatre in Rome, Italy',
        },
        {
          id: 3,
          src: 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1508804185872-d7badad00f7d?w=400',
          title: 'Great Wall of China',
          category: 'Monuments',
          description: 'Ancient fortification in northern China',
        },
        {
          id: 4,
          src: 'https://images.unsplash.com/photo-1587595431973-160d0d94add1?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1587595431973-160d0d94add1?w=400',
          title: 'Machu Picchu',
          category: 'Wonders',
          description: 'Inca citadel in the Andes Mountains of Peru',
        },
        {
          id: 5,
          src: 'https://images.unsplash.com/photo-1578895101408-1a36b834405b?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1578895101408-1a36b834405b?w=400',
          title: 'Petra',
          category: 'Wonders',
          description: 'Archaeological city in Jordan',
        },
        {
          id: 6,
          src: 'https://images.unsplash.com/photo-1518638150340-f706e86654de?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1518638150340-f706e86654de?w=400',
          title: 'Chichen Itza',
          category: 'Wonders',
          description: 'Mayan archaeological site in Mexico',
        },
        {
          id: 7,
          src: 'https://images.unsplash.com/photo-1549144511-f099e773c147?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1549144511-f099e773c147?w=400',
          title: 'Eiffel Tower',
          category: 'Landmarks',
          description: 'Iconic iron lattice tower in Paris, France',
        },
        {
          id: 8,
          src: 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?w=400',
          title: 'Big Ben',
          category: 'Landmarks',
          description: 'Clock tower in London, England',
        },
        {
          id: 9,
          src: 'https://images.unsplash.com/photo-1605649487212-47bdab064df7?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1605649487212-47bdab064df7?w=400',
          title: 'Pyramids of Giza',
          category: 'Ancient',
          description: 'Ancient Egyptian pyramids near Cairo',
        },
        {
          id: 10,
          src: 'https://images.unsplash.com/photo-1503152394-c571994fd383?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1503152394-c571994fd383?w=400',
          title: 'Parthenon',
          category: 'Ancient',
          description: 'Ancient Greek temple in Athens',
        },
        {
          id: 11,
          src: 'https://images.unsplash.com/photo-1555400038-63f5ba517a47?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1555400038-63f5ba517a47?w=400',
          title: 'Angkor Wat',
          category: 'Ancient',
          description: 'Temple complex in Cambodia',
        },
        {
          id: 12,
          src: 'https://images.unsplash.com/photo-1548013146-72479768bada?w=800',
          thumbnail: 'https://images.unsplash.com/photo-1548013146-72479768bada?w=400',
          title: 'Neuschwanstein Castle',
          category: 'Castles',
          description: 'Romanesque Revival palace in Bavaria, Germany',
        },
      ];

      setImages(mockImages);
      setFilteredImages(mockImages);
      setLoading(false);
    }
  };

  const categories = ['all', 'Monuments', 'Wonders', 'Landmarks', 'Ancient', 'Castles'];

  const openLightbox = useCallback((index) => {
    setLightboxIndex(index);
    setLightboxOpen(true);
  }, []);

  const handleImageLoad = useCallback((imageId) => {
    setLoadedImages(prev => new Set([...prev, imageId]));
  }, []);

  // Pagination calculations
  const totalPages = Math.ceil(filteredImages.length / imagesPerPage);
  const startIndex = (currentPage - 1) * imagesPerPage;
  const endIndex = startIndex + imagesPerPage;
  const currentImages = useMemo(() =>
    filteredImages.slice(startIndex, endIndex),
    [filteredImages, startIndex, endIndex]
  );

  const lightboxSlides = useMemo(() =>
    filteredImages.map(img => ({
      src: img.src,
      title: img.title,
      description: img.description,
    })),
    [filteredImages]
  );

  const handlePageChange = useCallback((newPage) => {
    setCurrentPage(newPage);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  return (
    <div className="min-h-screen pt-20">
      {/* Header */}
      <section className="bg-gradient-to-r from-primary-600 to-primary-800 text-white py-16">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <h1 className="text-4xl md:text-5xl font-bold mb-4">{t.gallery.title}</h1>
          <p className="text-xl text-primary-100">
            {t.gallery.subtitle}
          </p>
        </div>
      </section>

      {/* Category Filter */}
      <section className="bg-white shadow-sm sticky top-20 z-40">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
          <div className="flex flex-wrap gap-2">
            {categories.map((category) => (
              <button
                key={category}
                onClick={() => setSelectedCategory(category)}
                className={`px-6 py-2 rounded-lg font-medium transition-all duration-300 ${
                  selectedCategory === category
                    ? 'bg-primary-600 text-white shadow-md'
                    : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                }`}
              >
                {category === 'all' ? t.gallery.allCategories : category}
              </button>
            ))}
          </div>
        </div>
      </section>

      {/* Gallery Grid */}
      <section className="py-16">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="mb-8">
            <h2 className="text-3xl font-bold text-gray-900">
              {selectedCategory === 'all' ? t.gallery.allCategories : selectedCategory}
            </h2>
            <p className="text-gray-600 mt-2">
              {filteredImages.length} {filteredImages.length === 1 ? t.gallery.imageCount.singular : t.gallery.imageCount.plural}
            </p>
          </div>

          {loading ? (
            <div className="text-center py-12">
              <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-primary-600"></div>
              <p className="mt-4 text-gray-600">{t.gallery.loading}</p>
            </div>
          ) : filteredImages.length === 0 ? (
            <div className="text-center py-12">
              <p className="text-gray-500 text-lg">{t.gallery.noImages}</p>
            </div>
          ) : (
            <>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {currentImages.map((image, index) => {
                  const globalIndex = startIndex + index;
                  return (
                    <div
                      key={image.id}
                      className="group relative bg-white rounded-xl shadow-lg overflow-hidden cursor-pointer transform hover:scale-105 transition-all duration-300"
                      onClick={() => openLightbox(globalIndex)}
                    >
                      <div className="aspect-w-4 aspect-h-3 relative overflow-hidden bg-gray-200">
                        <img
                          src={image.thumbnail}
                          alt={image.title}
                          loading="lazy"
                          className="w-full h-64 object-cover group-hover:scale-110 transition-transform duration-500"
                          onLoad={() => handleImageLoad(image.id)}
                          style={{
                            opacity: loadedImages.has(image.id) ? 1 : 0,
                            transition: 'opacity 0.3s ease-in-out'
                          }}
                        />
                        {!loadedImages.has(image.id) && (
                          <div className="absolute inset-0 flex items-center justify-center">
                            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary-600"></div>
                          </div>
                        )}
                        <div className="absolute inset-0 bg-gradient-to-t from-black/70 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                          <div className="absolute bottom-0 left-0 right-0 p-4 text-white">
                            <h3 className="text-lg font-bold mb-1">{image.title}</h3>
                            <p className="text-sm text-gray-200 line-clamp-2">{image.description}</p>
                          </div>
                        </div>
                        <div className="absolute top-4 right-4 bg-white/90 backdrop-blur-sm px-3 py-1 rounded-full text-sm font-medium text-gray-700 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                          View
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Pagination */}
              {totalPages > 1 && (
                <div className="flex justify-center items-center gap-2 mt-12">
                  <button
                    onClick={() => handlePageChange(currentPage - 1)}
                    disabled={currentPage === 1}
                    className={`px-4 py-2 rounded-lg font-medium transition-all ${
                      currentPage === 1
                        ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                        : 'bg-white text-gray-700 hover:bg-primary-600 hover:text-white shadow-md'
                    }`}
                  >
                    Previous
                  </button>

                  <div className="flex gap-2">
                    {[...Array(totalPages)].map((_, i) => {
                      const pageNum = i + 1;
                      // Show first page, last page, current page, and pages around current
                      if (
                        pageNum === 1 ||
                        pageNum === totalPages ||
                        (pageNum >= currentPage - 1 && pageNum <= currentPage + 1)
                      ) {
                        return (
                          <button
                            key={pageNum}
                            onClick={() => handlePageChange(pageNum)}
                            className={`px-4 py-2 rounded-lg font-medium transition-all ${
                              currentPage === pageNum
                                ? 'bg-primary-600 text-white shadow-md'
                                : 'bg-white text-gray-700 hover:bg-gray-100 shadow-sm'
                            }`}
                          >
                            {pageNum}
                          </button>
                        );
                      } else if (
                        pageNum === currentPage - 2 ||
                        pageNum === currentPage + 2
                      ) {
                        return <span key={pageNum} className="px-2 py-2 text-gray-400">...</span>;
                      }
                      return null;
                    })}
                  </div>

                  <button
                    onClick={() => handlePageChange(currentPage + 1)}
                    disabled={currentPage === totalPages}
                    className={`px-4 py-2 rounded-lg font-medium transition-all ${
                      currentPage === totalPages
                        ? 'bg-gray-200 text-gray-400 cursor-not-allowed'
                        : 'bg-white text-gray-700 hover:bg-primary-600 hover:text-white shadow-md'
                    }`}
                  >
                    Next
                  </button>
                </div>
              )}
            </>
          )}

          {!loading && filteredImages.length === 0 && (
            <div className="text-center py-12">
              <svg className="w-16 h-16 mx-auto text-gray-400 mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
              </svg>
              <p className="text-gray-600 text-lg">No images found in this category</p>
            </div>
          )}
        </div>
      </section>

      {/* Lightbox */}
      <Lightbox
        open={lightboxOpen}
        close={() => setLightboxOpen(false)}
        slides={lightboxSlides}
        index={lightboxIndex}
      />
    </div>
  );
};

export default Gallery;
